function groupCommitsByType(messages) {
  const groups = {};
  for (const msg of messages) {
    const parsed = parseConventionalCommit(msg);
    const type = parsed ? parsed.type : 'unknown';
    groups[type] = (groups[type] || 0) + 1;
  }
  return groups;
}
